// 原Task服务仅同步调用；本表只证一封原信的本人接触，旧期限与钱货写者不被复制。
#include "task_personal_message_services.hpp"
#include "task_personal_message_detail.hpp"
namespace hanmo::resident {
Status validate_task_personal_message_services(const CommonStore& c,const TaskState& tasks,const TaskCatalog& catalog,const TaskPersonalMessageState* state,const TaskPersonalMessageServices* service){if(bool(state)!=(service!=nullptr))return common_failure("TaskPersonalMessageServicesMismatch");if(!service)return common_success();const auto& x=service->sources;if(state!=&x.state||&c!=&x.common||&tasks!=&x.tasks||&catalog!=&x.task_catalog||!tasks.message_handoffs||&*tasks.message_handoffs!=&x.handoffs||(tasks.message_handoffs->version!=3&&tasks.message_handoffs->version!=4)||(tasks.message_handoffs->version==4)!=tasks.personal_reports.has_value())return common_failure("TaskPersonalMessageCandidateRequired");return common_success();}
Status validate_task_personal_message_extension_pair(const TaskPersonalMessageCatalog& personal,const TaskExtensionCatalog* extensions){if(extensions)for(const auto& p:personal.policies)for(const auto& e:extensions->policies)if(p.offer_id==e.offer_id)return common_failure("TaskPersonalMessageDeadlineExtensionUnsupported",p.offer_id);return common_success();}
Status validate_task_personal_message_action_shape(const CommonStore& common,const TaskState& tasks,const TaskPersonalMessageState& state,const ActionCoreView& action,const TaskAction& params){const auto* source=personal_message_detail::start_for_action(state,action.id);const auto* task=tasks.tasks.find(params.task_id);if(state.version!=1||!source||!task||params.source_kind!=std::optional<StableId>{task_personal_message_source_kind}||action.kind!="deliver_message"||source->task_id!=task->id||source->offer_id!=params.offer_id||task->offer_id!=params.offer_id||task->assignee!=action.actor_id||source->carrier_actor_id!=action.actor_id||source->started_tick!=action.start_tick||source->recipient_actor_id!=params.context.provider_actor_id||action.participants!=std::vector<StableId>{source->carrier_actor_id,source->recipient_actor_id}||!personal_message_detail::context(params.context,source->recipient_declaration.declaration.meeting.context)||!common.state().facts.find(source->fact_id))return common_failure("TaskPersonalMessageActionSourceRequired",action.id);return common_success();}
bool task_personal_message_can_interrupt(const StableId& code){return code=="TaskPersonalMessageDeclarationChanged"||code=="TaskPersonalMessageOriginalLotMissing"||code=="TaskPersonalMessageAssetAuthorityMismatch"||code=="RecipientCapacity";}
}
